const listPerimetroRegistrato = `-- name: ListPerimetroRegistrato :many
WITH RECURSIVE perimetro(componente_id) AS (
    SELECT c.componente_id FROM componente c
     WHERE c.thread_id = $1 AND c.componente_id = $2
  UNION
    SELECT r.figlio_id FROM componente_relazione r
      JOIN perimetro p ON p.componente_id = r.padre_id
      JOIN componente f ON f.componente_id = r.figlio_id AND f.archiviato_il IS NULL
     WHERE r.thread_id = $1
)
SELECT c.componente_id, c.codice, c.rev, c.descrizione, c.tipo, c.archiviato_il
  FROM componente c
  JOIN perimetro p ON p.componente_id = c.componente_id
 WHERE c.thread_id = $1
 ORDER BY c.componente_id
`

type ListPerimetroRegistratoParams struct {
	ThreadID   uuid.UUID `json:"thread_id"`
	ProdottoID uuid.UUID `json:"prodotto_id"`
}

type ListPerimetroRegistratoRow struct {
	ComponenteID uuid.UUID      `json:"componente_id"`
	Codice       string         `json:"codice"`
	Rev          pgtype.Text    `json:"rev"`
	Descrizione  pgtype.Text    `json:"descrizione"`
	Tipo         TipoComponente `json:"tipo"`
	ArchiviatoIl *time.Time     `json:"archiviato_il"`
}

// Il perimetro registrato di un prodotto della RFQ: il prodotto e tutti i componenti che la working
// (componente_relazione) gli mette sotto, a ogni livello. E' lo stato di partenza «registrato» della prima versione
// di una bozza (contratto rev. 3 §6.6): il server lo ricostruisce da solo e lo confronta con quello che dicono le
// azioni. UNION (non UNION ALL): un ciclo nella working non fa girare la query all'infinito. I figli archiviati non
// ci sono (come v_componente_albero e il perimetro chiuso della conferma: la conferma non li certifica), neanche se
// un arco rimasto li tocca (revisioni della notte, R-11 / RD-12).
func (q *Queries) ListPerimetroRegistrato(ctx context.Context, arg ListPerimetroRegistratoParams) ([]ListPerimetroRegistratoRow, error) {
	rows, err := q.db.Query(ctx, listPerimetroRegistrato, arg.ThreadID, arg.ProdottoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPerimetroRegistratoRow{}
	for rows.Next() {
		var i ListPerimetroRegistratoRow
		if err := rows.Scan(
			&i.ComponenteID,
			&i.Codice,
			&i.Rev,
			&i.Descrizione,
			&i.Tipo,
			&i.ArchiviatoIl,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const ultimoEventoDistintaBozza = `-- name: UltimoEventoDistintaBozza :one
SELECT COALESCE(max(e.n), 0)::int AS n FROM distinta_bozza_evento e
  JOIN distinta_bozza b ON b.bozza_id = e.bozza_id
 WHERE e.bozza_id = $1 AND b.thread_id = $2
`

type UltimoEventoDistintaBozzaParams struct {
	BozzaID  uuid.UUID `json:"bozza_id"`
	ThreadID uuid.UUID `json:"thread_id"`
}

// Il numero dell'ultimo evento di una bozza della RFQ (0 se non ce ne sono): il prossimo e' questo + 1.
func (q *Queries) UltimoEventoDistintaBozza(ctx context.Context, arg UltimoEventoDistintaBozzaParams) (int32, error) {
	row := q.db.QueryRow(ctx, ultimoEventoDistintaBozza, arg.BozzaID, arg.ThreadID)
	var n int32
	err := row.Scan(&n)
	return n, err
}
